CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_caseinvestigation]
AS
BEGIN

	/*
		Raj Maddala, 2023-12-06 15:30, Included audit table insert for apuk_status
	*/

	INSERT INTO [Snapshots].[tblCaseInvestigationStatus_Audit]
	(
		[apuk_caseinvestigationid],
		[Snapshot_Date],
		[modifiedon],
		[apuk_status_previous],
		[apuk_status_current]
	)
	SELECT 
		wrk.[apuk_caseinvestigationid],
		GETDATE(),
		wrk.[modifiedon],
		CASE WHEN ISNULL(wrk.[apuk_status], 0) <> ISNULL(tgt.[apuk_status], 0) THEN tgt.[apuk_status] END,
		CASE WHEN ISNULL(wrk.[apuk_status], 0) <> ISNULL(tgt.[apuk_status], 0) THEN wrk.[apuk_status] END
	FROM [staging_ce].[apuk_caseinvestigation] wrk
		INNER JOIN [synapse_ce].[apuk_caseinvestigation] tgt
			ON wrk.[apuk_caseinvestigationid] = tgt.[apuk_caseinvestigationid]
	WHERE 
		(
			ISNULL(wrk.[apuk_status], 0) <> ISNULL(tgt.[apuk_status], 0) 
		)


	-- Update target with the current changes

	UPDATE tgt SET 
		tgt.[apuk_ageofcase] = 	CASE
									WHEN stg.[apuk_caseclosuredate] IS NULL THEN DATEDIFF(day, stg.createdon, GETDATE())
									ELSE stg.[apuk_ageofcase]
								END,
		tgt.[apuk_anonymous] = stg.[apuk_anonymous],
		tgt.[apuk_areaofbreach] = stg.[apuk_areaofbreach],
		tgt.[apuk_areaofbreach_entitytype] = stg.[apuk_areaofbreach_entitytype],
		tgt.[apuk_areaofbreach2] = stg.[apuk_areaofbreach2],
		tgt.[apuk_areaofbreach2_entitytype] = stg.[apuk_areaofbreach2_entitytype],
		tgt.[apuk_areaofbreach2name] = stg.[apuk_areaofbreach2name],
		tgt.[apuk_areaofbreach3] = stg.[apuk_areaofbreach3],
		tgt.[apuk_areaofbreach3_entitytype] = stg.[apuk_areaofbreach3_entitytype],
		tgt.[apuk_areaofbreach3name] = stg.[apuk_areaofbreach3name],
		tgt.[apuk_areaofbreachname] = stg.[apuk_areaofbreachname],
		tgt.[apuk_areaofpractice] = stg.[apuk_areaofpractice],
